add_filter( 'the_excerpt', 'perfectpixel_edit_link_in_archives', 30 );
add_filter( 'the_content', 'perfectpixel_edit_link_in_archives', 30 );

function perfectpixel_edit_link_in_archives( $content ) {
	if ( is_admin() || is_feed() || ! in_the_loop() || ! current_user_can( 'edit_post', get_the_ID() ) ) {
		return $content;
	}
	$link = get_edit_post_link( get_the_ID() );
	if ( ! $link ) {
		return $content;
	}
	return $content . '<p class="perfectpixel-edit-link"><a href="' . esc_url( $link ) . '">' . esc_html( '{{archive_edit_link_text}}' ) . '</a></p>';
}
